from aide import L, st, e, v, d, ch, li, od

UNIT = ("Écrire comme un pro", "🧑‍💼", "Rédiger des textes clairs, structurés et convaincants.", [

L("🧾", "La nominalisation",
  "Transformer des verbes en noms pour un style formel.",
  [st("🧾", "La nominalisation transforme un verbe ou un adjectif en nom : decide → decision, fail → failure, available → availability."),
   st("🎩", "Elle rend un texte plus formel et compact : « We decided to expand » → The decision to expand…"),
   st("⚖️", "Mais trop de noms alourdit le texte : utilise-la dans les rapports, pas dans les courriels amicaux."),
   st("🔗", "Suffixes fréquents : -tion, -ment, -ance/-ence, -ity, -al (approve → approval).")],
  [e("🧾", "The decision to expand was made in May.", "La décision d’agrandir a été prise en mai."),
   e("📉", "The failure of the project surprised everyone.", "L’échec du projet a surpris tout le monde."),
   e("✅", "We are waiting for the approval of the budget.", "Nous attendons l’approbation du budget."),
   e("📅", "Please confirm your availability.", "Veuillez confirmer votre disponibilité."),
   e("📈", "The improvement in sales is significant.", "L’amélioration des ventes est importante.")],
  [v("🧾", "decision", "décision", "a difficult decision"),
   v("📉", "failure", "échec", "a complete failure"),
   v("✅", "approval", "approbation", "pending approval"),
   v("📅", "availability", "disponibilité", "Check the availability."),
   v("📈", "improvement", "amélioration", "a clear improvement"),
   v("🔍", "analysis", "analyse", "a detailed analysis")],
  [d("Draft", "We analyzed the data and we improved the process.", "Nous avons analysé les données et amélioré le processus."),
   d("Editor", "For the report, try nominalization.", "Pour le rapport, essaie la nominalisation."),
   d("Draft", "« The analysis of the data led to an improvement in the process. »", "« L’analyse des données a mené à une amélioration du processus. »"),
   d("Editor", "Exactly. More formal and more concise.", "Exactement. Plus formel et plus concis.")],
  "« Disponibilité » = availability, mais « disponible » = available. Et « une analyse » = an analysis (pluriel : analyses).",
  [ch("Verb « approve » → noun ___.", ["approvement", "approval", "approvation"], 1, "approve → approval."),
   ch("Verb « fail » → noun ___.", ["failure", "failment", "failness"], 0, "fail → failure."),
   ch("Adjective « available » → noun ___.", ["availableness", "availability", "availment"], 1, "available → availability."),
   ch("Formal: « We decided to close » → « The ___ to close… »", ["decide", "decision", "deciding"], 1, "decision."),
   li("The analysis led to an improvement.", ["The analysis led to an improvement.", "The analyze led to an improvement.", "The analysis lead to an improvement."], 0, "analysis, led (passé)."),
   od("The decision to expand was made in May", "La décision d’agrandir a été prise en mai", "Nominalisation.")]),

L("📄", "L’essai argumentatif",
  "Structurer un essai convaincant en anglais.",
  [st("🎯", "Introduction : contexte + thèse claire (thesis statement) à la fin du paragraphe. This essay argues that…"),
   st("🧱", "Chaque paragraphe : une topic sentence, une preuve ou un exemple, une explication, un lien avec la thèse."),
   st("⚔️", "Un paragraphe de contre-argument montre la maturité : Critics argue that… However, …"),
   st("🏁", "Conclusion : reformule la thèse, résume, ouvre sur une perspective. Pas de nouvelles idées!")],
  [e("🎯", "This essay argues that public transit should be free.", "Cet essai soutient que le transport en commun devrait être gratuit."),
   e("📊", "For instance, Luxembourg made all public transit free in 2020.", "Par exemple, le Luxembourg a rendu tout le transport en commun gratuit en 2020."),
   e("⚔️", "Critics argue that it would be too expensive.", "Les critiques soutiennent que ce serait trop coûteux."),
   e("🔁", "However, the savings in road maintenance would offset the cost.", "Cependant, les économies en entretien des routes compenseraient le coût."),
   e("🏁", "In conclusion, free transit benefits everyone.", "En conclusion, le transport gratuit profite à tous.")],
  [v("🎯", "thesis statement", "énoncé de thèse", "Write a clear thesis statement."),
   v("📊", "evidence", "preuves", "Support it with evidence."),
   v("⚔️", "counterargument", "contre-argument", "Address the counterargument."),
   v("⚖️", "offset", "compenser", "The benefits offset the costs."),
   v("📌", "for instance", "par exemple", "For instance, …"),
   v("🏁", "in conclusion", "en conclusion", "In conclusion, …")],
  [d("Student", "Where should I put my thesis?", "Où devrais-je mettre ma thèse?"),
   d("Professor", "At the end of the introduction, in one clear sentence.", "À la fin de l’introduction, en une phrase claire."),
   d("Student", "Should I mention the opposite opinion?", "Devrais-je mentionner l’opinion contraire?"),
   d("Professor", "Yes, and then explain why it’s weaker than yours.", "Oui, puis explique pourquoi elle est moins solide que la tienne.")],
  "La dissertation française annonce souvent la thèse à la fin. En anglais, la thèse est annoncée dès l’introduction : le lecteur sait tout de suite où tu vas.",
  [ch("The sentence that states your main argument is the ___.", ["thesis statement", "conclusion", "hook"], 0, "thesis statement."),
   ch("___ argue that the plan is too costly.", ["Critics", "Criticals", "Critiques"], 0, "Critics = les détracteurs."),
   ch("The savings would ___ the cost. (compenser)", ["offset", "outset", "upset"], 0, "offset = compenser."),
   ch("In the conclusion, you should NOT ___.", ["restate the thesis", "add new ideas", "summarize"], 1, "Pas de nouvelles idées en conclusion."),
   li("This essay argues that transit should be free.", ["This essay argues that transit should be free.", "This essay argues that transit could be free.", "This essay agrees that transit should be free."], 0, "argues that = soutient que."),
   od("Critics argue that it would be too expensive", "Les critiques soutiennent que ce serait trop coûteux", "Présenter un contre-argument.")]),

L("💼", "La correspondance formelle",
  "Rédiger une lettre de motivation et des messages délicats.",
  [st("💼", "Lettre de motivation : I am writing to apply for the position of… advertised on…"),
   st("🌟", "Mettre en valeur : I have extensive experience in… / I am confident that my skills would be an asset to your team."),
   st("🙅", "Refus diplomatique : Thank you for your offer. Unfortunately, we are unable to… / After careful consideration, …"),
   st("🏁", "Fin : I would welcome the opportunity to discuss… / Thank you for your time and consideration. Sincerely,")],
  [e("💼", "I am writing to apply for the position of marketing manager.", "Je vous écris pour poser ma candidature au poste de directeur marketing."),
   e("🌟", "I am confident that my skills would be an asset to your team.", "Je suis convaincu que mes compétences seraient un atout pour votre équipe."),
   e("🙅", "After careful consideration, we have decided not to proceed.", "Après mûre réflexion, nous avons décidé de ne pas donner suite."),
   e("🤝", "I would welcome the opportunity to discuss my application.", "Je serais heureux d’avoir l’occasion de discuter de ma candidature."),
   e("🙏", "Thank you for your time and consideration.", "Merci de votre temps et de votre attention.")],
  [v("💼", "apply for", "postuler à", "I’m applying for the job."),
   v("🌟", "an asset", "un atout", "She’s an asset to the team."),
   v("📚", "extensive experience", "vaste expérience", "extensive experience in finance"),
   v("🙅", "unable to", "dans l’impossibilité de", "We are unable to accept."),
   v("🤔", "after careful consideration", "après mûre réflexion", "After careful consideration, …"),
   v("✍️", "Sincerely,", "Veuillez agréer… (formule finale)", "Sincerely, Anne Roy")],
  [d("Lettre", "Dear Hiring Manager,", "Madame, Monsieur,"),
   d("Lettre", "I am writing to apply for the position of project coordinator.", "Je vous écris pour poser ma candidature au poste de coordonnateur de projet."),
   d("Lettre", "With extensive experience in event planning, I am confident I would be an asset to your team.", "Fort d’une vaste expérience en organisation d’événements, je suis convaincu que je serais un atout pour votre équipe."),
   d("Lettre", "I would welcome the opportunity to discuss my application.", "Je serais heureux d’avoir l’occasion de discuter de ma candidature."),
   d("Lettre", "Sincerely, Julien Paré", "Veuillez agréer mes salutations distinguées, Julien Paré")],
  "Les longues formules de politesse françaises (« Veuillez agréer… ») n’existent pas en anglais. Un simple « Sincerely, » ou « Best regards, » suffit.",
  [ch("I am writing to apply ___ the position of analyst.", ["to", "for", "at"], 1, "apply for a position."),
   ch("My experience would be an ___ to your company.", ["asset", "assist", "access"], 0, "an asset = un atout."),
   ch("After careful ___, we have chosen another candidate.", ["consider", "consideration", "considering"], 1, "after careful consideration."),
   ch("We are ___ to offer you the position.", ["unable", "unpossible", "incapable of"], 0, "unable to = dans l’impossibilité de."),
   li("Thank you for your time and consideration.", ["Thank you for your time and consideration.", "Thank you for your time and conversation.", "Thanks for your time and consideration."], 0, "Formule de clôture."),
   od("I would welcome the opportunity to discuss my application", "Je serais heureux de discuter de ma candidature", "Formule finale polie.")]),

L("🧹", "Réviser son texte",
  "Corriger les erreurs typiques des francophones à l’écrit.",
  [st("🔠", "Majuscules : jours, mois, langues, nationalités (Monday, May, French). Dans les titres : majuscule aux mots importants."),
   st("📍", "Ponctuation : pas d’espace avant ? ! : ; Les guillemets sont “ ” (pas « »). Virgule obligatoire après une introduction longue."),
   st("🔀", "Ordre des mots : adverbe pas entre le verbe et son complément. « I like very much coffee » → I like coffee very much."),
   st("🎭", "Gallicismes : « make a demand » (= exiger) pour « faire une demande » (= make a request), « since three years » au lieu de « for three years ».")],
  [e("🔠", "We met on Monday, May 5, in a French café.", "Nous nous sommes rencontrés le lundi 5 mai, dans un café français."),
   e("❓", "Are you coming?", "Viens-tu?"),
   e("☕", "I like coffee very much.", "J’aime beaucoup le café."),
   e("🙋", "I’d like to ask a question.", "J’aimerais poser une question."),
   e("📅", "I’ve worked here for three years.", "Je travaille ici depuis trois ans.")],
  [v("🧹", "proofread", "relire, réviser", "Always proofread your emails."),
   v("🔠", "capital letter", "majuscule", "Use a capital letter."),
   v("📍", "punctuation", "ponctuation", "Check your punctuation."),
   v("🎭", "gallicism", "gallicisme", "Avoid gallicisms."),
   v("🔀", "word order", "ordre des mots", "The word order is wrong."),
   v("✅", "spell-check", "correcteur orthographique", "Run a spell-check.")],
  [d("Editor", "You wrote « I am agree with the proposition ».", "Tu as écrit « I am agree with the proposition »."),
   d("Writer", "What’s wrong with it?", "Qu’est-ce qui ne va pas?"),
   d("Editor", "It’s « I agree with the proposal ». Agree is a verb.", "C’est « I agree with the proposal ». Agree est un verbe."),
   d("Writer", "And « proposal », not « proposition »?", "Et « proposal », pas « proposition »?"),
   d("Editor", "Right. In business, a proposal is a formal suggestion.", "Exact. En affaires, un « proposal » est une proposition formelle.")],
  "Relis toujours ton texte en cherchant UNE erreur à la fois : d’abord les majuscules, ensuite les espaces avant la ponctuation, puis les faux amis.",
  [ch("Correct: ___", ["I speak french.", "I speak French.", "i speak French."], 1, "Les langues prennent une majuscule."),
   ch("Correct: ___", ["Are you ready ?", "Are you ready?", "Are you ready ¿"], 1, "Pas d’espace avant le point d’interrogation."),
   ch("Correct: « I like ___ »", ["very much chocolate", "chocolate very much", "much very chocolate"], 1, "Adverbe après le complément."),
   ch("« Je travaille ici depuis 3 ans » = ___", ["I work here since 3 years.", "I’ve worked here for 3 years.", "I work here for 3 years."], 1, "Present perfect + for."),
   li("I agree with the proposal.", ["I agree with the proposal.", "I am agree with the proposal.", "I agree with the proposition."], 0, "agree (verbe) + proposal."),
   od("I like coffee very much", "J’aime beaucoup le café", "very much en fin de phrase.")]),

L("📈", "Résumer et paraphraser",
  "Reformuler les idées d’un texte avec tes propres mots.",
  [st("📈", "Résumer : garder seulement les idées principales, en 1/4 ou 1/3 de la longueur originale."),
   st("🔁", "Paraphraser : même sens, mots et structure différents. Change la structure, utilise des synonymes, change la classe des mots (decide → decision)."),
   st("🗣️", "Introduire : The author argues that… / According to the article, … / The study suggests that…"),
   st("⚠️", "Ne copie pas des phrases entières : c’est du plagiat. Et ne change pas le sens!")],
  [e("🗣️", "The author argues that remote work increases productivity.", "L’auteur soutient que le télétravail augmente la productivité."),
   e("📰", "According to the article, prices will rise.", "Selon l’article, les prix vont augmenter."),
   e("🔁", "Original: « Many people decided to leave the city. »", "Original : « Beaucoup de gens ont décidé de quitter la ville. »"),
   e("🔁", "Paraphrase: « A large number of residents chose to move out. »", "Paraphrase : « Un grand nombre de résidents ont choisi de déménager. »"),
   e("✂️", "In short, the study shows mixed results.", "En bref, l’étude montre des résultats mitigés.")],
  [v("📈", "summarize", "résumer", "Summarize the text in 100 words."),
   v("🔁", "paraphrase", "paraphraser", "Paraphrase this sentence."),
   v("🗣️", "the author argues", "l’auteur soutient", "The author argues that…"),
   v("📋", "main idea", "idée principale", "What’s the main idea?"),
   v("🧪", "mixed results", "résultats mitigés", "The test had mixed results."),
   v("⚠️", "plagiarism", "plagiat", "Plagiarism is serious.")],
  [d("Teacher", "Can you summarize the article in two sentences?", "Peux-tu résumer l’article en deux phrases?"),
   d("Student", "The author argues that four-day weeks improve well-being.", "L’auteur soutient que la semaine de quatre jours améliore le bien-être."),
   d("Teacher", "Good. And the second?", "Bien. Et la deuxième?"),
   d("Student", "However, the results for productivity are mixed.", "Cependant, les résultats sur la productivité sont mitigés.")],
  "Pour paraphraser, cache le texte original et écris de mémoire. Puis compare : le sens doit être le même, les mots différents.",
  [ch("Keeping only the main ideas is called ___.", ["summarizing", "paraphrasing", "plagiarizing"], 0, "summarize = résumer."),
   ch("___ to the study, sleep improves memory.", ["According", "Following", "Based"], 0, "According to = selon."),
   ch("A good paraphrase changes the words but keeps the ___.", ["meaning", "length", "structure"], 0, "Même sens."),
   ch("Copying sentences without credit is ___.", ["plagiarism", "paraphrase", "summary"], 0, "plagiarism = plagiat."),
   li("The author argues that remote work increases productivity.", ["The author argues that remote work increases productivity.", "The author argues that remote work decreases productivity.", "The authors argue that remote work increases productivity."], 0, "argues = soutient."),
   od("In short the study shows mixed results", "En bref, l’étude montre des résultats mitigés", "In short = en bref.")]),
])
